    assert.deepEqual(entries.map(e => e.outcome), ["ok", "refused", "failed"]);
    assert.equal(text.includes("must-not-survive"), false);
    assert.equal(entries[0].result.password, "[redacted]");
    assert.equal(verifyChain("main").ok, true);
